}

.nav-links a:hover { opacity: 1; text-decoration: none; }

.hamburger {
  display: none;
  background: none;
  border: none;
  color: #fff;
  font-size: 24px;
  cursor: pointer;
  padding: 8px;
}

.mobile-nav {
  display: none;
  padding: 16px 0;
  border-top: 1px solid rgba(255,255,255,0.1);
}

.mobile-nav.active { display: block; }

.mobile-nav a {
  display: block;
  padding: 12px 0;
  color: #fff;
