.learn-section h2 {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 20px;
  color: var(--primary);
}

.welcome-cta {
  background: linear-gradient(135deg, var(--bg-secondary) 0%, #E8F4FD 100%);
  border-radius: var(--radius-lg);
  padding: 32px;
  text-align: center;
  margin-bottom: 48px;
}

.welcome-cta h2 {
  font-size: 24px;
  margin-bottom: 12px;
}

.welcome-cta p {
  color: var(--text-muted);
  margin-bottom: 20px;
}

.daily-challenge {
  background: linear-gradient(135deg, #FEF3C7 0%, #FDE68A 100%);
  border-radius: var(--radius-lg);
  padding: 32px;
  text-align: center;
}

.daily-challenge h3 {
  font-size: 20px;
  margin-bottom: 16px;
}

.challenge-links {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.link-group {
  display: flex;
  gap: 12px;
  align-items: center;
}

/* Two Column Layout */
.two-column {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
}

@media (max-width: 768px) {
  .two-column { grid-template-columns: 1fr; }
  .featured-title { font-size: 22px; }
  .page-header h1 { font-size: 28px; }
  .donate-hero { padding: 40px 24px; }
  .donate-hero h1 { font-size: 28px; }
}

